CGAL::Bounded_side result = CGAL::ON_UNBOUNDED_SIDE;
if (polygon.empty()) return result;

Point_2 p = point;
size_t n = polygon.size();

// Check if point lies on any edge
for (size_t i = 0; i < n; ++i) {
    const Point_2& a = polygon[i];
    const Point_2& b = polygon[(i + 1) % n];
    if (CGAL::collinear(a, b, p)) {
        if (CGAL::do_intersect(CGAL::Segment_2(a, b), CGAL::Point_2(p))) {
            return CGAL::ON_BOUNDARY;
        }
    }
}

// Ray casting: shoot a horizontal ray to the right
int crossings = 0;
for (size_t i = 0; i < n; ++i) {
    const Point_2& a = polygon[i];
    const Point_2& b = polygon[(i + 1) % n];

    // Skip horizontal edges
    if (a.y() == b.y()) continue;

    // Check if edge crosses the horizontal ray from point to right
    if ((a.y() > p.y()) != (b.y() > p.y())) {
        // Compute x-coordinate of intersection
        double x_intersect = a.x() + (b.x() - a.x()) * (p.y() - a.y()) / (b.y() - a.y());
        if (x_intersect > p.x()) {
            crossings++;
        }
    }
}

result = (crossings % 2 == 1) ? CGAL::ON_BOUNDED_SIDE : CGAL::ON_UNBOUNDED_SIDE;
return result;

